# LIT configuration for the CQ frontend (clang intrinsic-surface) tests.
# The site config (generated by CMake) injects CQ_CLANG_EXECUTABLE,
# CQ_FILECHECK_EXECUTABLE and CQ_INCLUDE_FLAG into the `config` namespace
# before this file is loaded.

import os
import lit.formats

config.name = "CQ Frontend"
config.test_format = lit.formats.ShTest(execute_external=True)
config.suffixes = [".c"]
config.test_source_root = os.path.dirname(os.path.abspath(__file__))

# test_exec_root may be overridden by the site config (build-dir output).
if not getattr(config, "test_exec_root", None):
    config.test_exec_root = config.test_source_root

# Substitutions. These come in from the site config; fall back to env so
# the file remains usable when invoked without a generated site config
# (e.g. for an editor's lit-mode preview).
clang = getattr(config, "clang", None) or os.environ.get("CQ_CLANG", "clang-19")
filecheck = getattr(config, "filecheck", None) or os.environ.get("FILECHECK", "FileCheck-19")
# cq_include expands to "-I<source>/include" so RUN lines can use
# `-include CQ.h` without spelling out the include path themselves.
cq_include = getattr(config, "cq_include", None) or os.environ.get("CQ_INCLUDE", "")

# %clang expands to the clang binary; %cq_include to the -I flag for the
# CQ header directory. Tests typically write:
#   // RUN: %clang %cq_include -O1 -emit-llvm -include CQ.h -S %s -o - | %filecheck %s
config.substitutions.append(("%clang", clang))
config.substitutions.append(("%filecheck", filecheck))
config.substitutions.append(("%cq_include", cq_include))

# Add the LLVM tools directory to PATH so bundled wrappers like `not`
# (used by negative LIT fixtures to invert clang's exit code) resolve.
# `clang` is typically `/usr/lib/llvm-19/bin/clang-19`; the wrapper sits in
# the same directory. Falls back gracefully if `clang` is a bare name.
_llvm_bin = os.path.dirname(clang) if os.path.dirname(clang) else ""
if _llvm_bin:
    config.environment["PATH"] = _llvm_bin + os.pathsep + os.environ.get(
        "PATH", ""
    )
